import base64
import subprocess
import sys
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "qiskit", "qiskit-aer", "scikit-learn", "pandas", "matplotlib", "pylatexenc"], check=True)
import matplotlib
matplotlib.use("Agg")
SOURCES = {
  "Day17/1-2.py": "",
  "Day17/1-1.py": "",
  "Day17/2-1.py": "",
  "Day16/3-1.py": "",
  "Day16/3-3.py": "",
  "Day16/3-4.py": "",
  "Day16/3-2.py": "",
  "Day16/2-4.py": "",
  "Day16/2-3.py": "",
  "Day16/2-2.py": "",
  "Day16/2-1.py": ""
}
for name, payload in SOURCES.items():
    print(f"COLAB_SOURCE_START {name}")
    code = base64.b64decode(payload).decode("utf-8")
    scope = {"__name__": "__main__", "__file__": name}
    exec(compile(code, name, "exec"), scope, scope)
    print(f"COLAB_SOURCE_OK {name}")
print("COLAB_DAY16_DAY17_SOURCE_EXECUTION_OK")
